def chain_of_tokens(tokens):
    tokens = tokens.split(',')
    tokens.sort()
    result = []
    current = tokens[0]
    for token in tokens[1:]:
        if token == current:
            result.append(current)
        else:
            result.append(current)
            current = token
    result.append(current)
    return ','.join(result)
